#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
set -eu
cd "$(dirname "$0")"
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ -e images/yugabytedb-yugabyte-2025.2.8.1-b8-arm64-oci ] || "$F" docker.io/yugabytedb/yugabyte sha256:ba23ef3605acfb5c8f983ded0edc00c73296820c34886c960b1cab894e1de516 yugabytedb/yugabyte:2025.2.8.1-b8 images/yugabytedb-yugabyte-2025.2.8.1-b8-arm64-oci
[ -f images/yugabytedb-yugabyte-2025.2.8.1-b8-amd64.docker.tar ] || "$F" docker.io/yugabytedb/yugabyte sha256:de5340a195f290ec241f877db0f6d9b3d56bdb515f0051d348e793849623ccf3 yugabytedb/yugabyte:2025.2.8.1-b8 images/yugabytedb-yugabyte-2025.2.8.1-b8-amd64.docker.tar
ls -ld images/yugabytedb-yugabyte-2025.2.8.1-b8-amd64.docker.tar images/yugabytedb-yugabyte-2025.2.8.1-b8-arm64-oci
